package local.tvmorph.tv;
import android.content.Context;
import android.graphics.*;
import android.widget.Button;
final class PlayerSettingRow extends Button {
  private final Paint ink=new Paint(3);private final boolean choice,checked;
  PlayerSettingRow(Context context,String label,boolean option,boolean selected){super(context);choice=option;checked=selected;setText(label);setTextColor(PlayerPalette.text(context));setShadowLayer(2,0,1,PlayerPalette.alpha(PlayerPalette.surface(context),210));setTextSize(13);setAllCaps(false);setSingleLine(true);setEllipsize(android.text.TextUtils.TruncateAt.END);setGravity(android.view.Gravity.CENTER_VERTICAL|android.view.Gravity.START);float d=getResources().getDisplayMetrics().density;setPadding((int)(d*16),0,(int)(d*34),0);setMinHeight(0);setMinimumHeight(0);setBackgroundColor(Color.TRANSPARENT);setLayerType(LAYER_TYPE_SOFTWARE,null);}
  @Override protected void onDraw(Canvas c){int accent=PlayerPalette.accent(getContext()),surface=PlayerPalette.surface(getContext());float d=getResources().getDisplayMetrics().density;RectF r=new RectF(d, d,getWidth()-d,getHeight()-d);ink.setStyle(Paint.Style.FILL);ink.setShader(new LinearGradient(0,0,getWidth(),getHeight(),new int[]{PlayerPalette.alpha(isFocused()?PlayerPalette.shade(accent,.26f):checked?PlayerPalette.shade(accent,.17f):surface,40),PlayerPalette.alpha(PlayerPalette.shade(surface,.65f),26)},null,Shader.TileMode.CLAMP));c.drawRoundRect(r,8*d,8*d,ink);ink.clearShadowLayer();ink.setShader(null);ink.setStyle(Paint.Style.STROKE);ink.setStrokeWidth(d*.7f);ink.setColor(isFocused()?PlayerPalette.text(getContext()):checked?PlayerPalette.alpha(accent,140):PlayerPalette.alpha(accent,45));c.drawRoundRect(r,8*d,8*d,ink);super.onDraw(c);float x=getWidth()-18*d,y=getHeight()/2f;ink.setStrokeWidth(1.4f*d);if(choice&&checked){ink.setStyle(Paint.Style.FILL);ink.setColor(accent);c.drawCircle(x,y,7*d,ink);ink.setStyle(Paint.Style.STROKE);ink.setColor(PlayerPalette.surface(getContext()));Path p=new Path();p.moveTo(x-3*d,y);p.lineTo(x-d,y+2*d);p.lineTo(x+3*d,y-3*d);c.drawPath(p,ink);}else if(!choice){ink.setColor(PlayerPalette.alpha(PlayerPalette.text(getContext()),180));Path p=new Path();if(isActivated()){p.moveTo(x-3*d,y-2*d);p.lineTo(x,y+d);p.lineTo(x+3*d,y-2*d);}else{p.moveTo(x-2*d,y-3*d);p.lineTo(x+d,y);p.lineTo(x-2*d,y+3*d);}c.drawPath(p,ink);}}
}

